export type Difficulty = 'Fácil' | 'Médio' | 'Difícil';
export type TipoPrato = 'doce' | 'salgado';

export interface RecipeIngredient {
  /** Matches IngredientOption.query from ingredients.ts */
  query: string;
  /** Display text with quantity, e.g. "2 ovos" */
  display: string;
  /** Universal staples (água, etc.) that aren't selectable ingredients and don't affect match % */
  staple?: boolean;
}

export interface LocalRecipe {
  id: string;
  titulo: string;
  emoji: string;
  tipo: TipoPrato;
  tempoPreparoMinutos: number;
  dificuldade: Difficulty;
  porcoes: number;
  calorias: number;
  ingredientes: RecipeIngredient[];
  modoPreparo: string[];
  /** Matches IngredientOption.query from EQUIPAMENTOS in ingredients.ts — equipamento necessário para o preparo */
  equipamento: string[];
}

